<script setup lang="ts">
import { useCmsI18n } from '@/composables/useCmsI18n';
import type { FormData } from '../types';
const { t } = useCmsI18n();
// 放在脚本里：单行模板中静态属性含 // 会让 vue-tsc 生成的代码丢失 v-for 作用域。
const externalUrlPlaceholder = 'https://example.com';
defineProps<{items:FormData[];targets:FormData[];canStatus?:boolean;depth?:number}>();
</script>
<template><div v-for="(item,index) in items" :key="index" class="menu-item"><div class="menu-row"><el-input v-model="item.title" :placeholder="t('cms.labels.displayName')" /><el-select v-model="item.target_type" @change="item.target_id=''"><el-option :label="t('cms.labels.externalLink')" value="external" /><el-option :label="t('cms.labels.category')" value="category" /><el-option :label="t('cms.labels.contentPage')" value="content" /><el-option :label="t('cms.labels.home')" value="home" /></el-select><el-input v-if="item.target_type==='external'" v-model="item.external_url" :placeholder="externalUrlPlaceholder" /><el-select v-else v-model="item.target_id" filterable :placeholder="t('cms.labels.selectTarget')"><el-option v-for="target in targets.filter(row=>row.type===item.target_type)" :key="`${target.type}:${target.id}`" :label="target.title" :value="target.id" /></el-select><el-switch :model-value="item.status===undefined||!!Number(item.status)" :disabled="!canStatus" @change="item.status=$event?1:0" /><el-button v-if="(depth||0)<15" link @click="(item.children ||= []).push({title:'',target_type:'external',external_url:''})">{{ t('cms.labels.addChild') }}</el-button><el-button link type="danger" @click="items.splice(index,1)">{{ t('cms.labels.remove') }}</el-button></div><MenuItemsEditor v-if="item.children?.length" :items="item.children" :targets="targets" :can-status="canStatus" :depth="(depth||0)+1" /></div></template>
<style scoped>.menu-item{border-left:2px solid var(--el-border-color-light);padding-left:12px;margin:16px 0}.menu-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.menu-row .el-input,.menu-row .el-select{width:190px}</style>
